package com.app.entity;
import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="society_roster_assignments") @Data @Builder @NoArgsConstructor @AllArgsConstructor
public class SocietyRosterAssignment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="account_id",nullable=false) private Account account; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="shift_id",nullable=false) private SocietyShift shift; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="staff_id") private SocietyStaff staff; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="agency_worker_id") private SocietyAgencyWorker agencyWorker; @Column(nullable=false) private String postName; @Column(nullable=false) private LocalDate effectiveFrom; private LocalDate effectiveTo; @Column(nullable=false) @Builder.Default private Boolean active=true; @Column(nullable=false,updatable=false) @Builder.Default private LocalDateTime createdAt=LocalDateTime.now(); @Column(nullable=false) @Builder.Default private LocalDateTime updatedAt=LocalDateTime.now(); @PreUpdate void touch(){updatedAt=LocalDateTime.now();} }
